// What a slide needs to look on the canvas exactly as the Mac worker renders it: the brand's
// brand.css (generated by design-kit from the approved profile's tokens — or the neutral default
// the worker falls back to), where its files are (`tokens.fileAssets`: brand path → asset id),
// and the patch context the worker validates edits with (brand colour and font tokens).
import type { BrandProfile } from "@studio/contract";
import {
  type BrandTokens,
  brandPatchContext,
  colorValue,
  generateBrandCss,
  NEUTRAL_BRAND_TOKENS,
  parseBrandTokens,
} from "@studio/design-kit/brand";
import type { PatchContext } from "@studio/design-kit/patch";

export interface BrandSwatch {
  token: string;
  value: string;
  use: string | null;
}

export interface BrandFontRole {
  role: string;
  family: string;
}

export interface RenderKit {
  mode: "approved" | "neutral";
  tokens: BrandTokens;
  /** brand.css with its font URLs pointing at the asset store. */
  css: string;
  /** Brand file path (`fonts/x.woff2`, `logos/y.png`) → asset id. */
  files: Record<string, string>;
  ctx: PatchContext;
  swatches: BrandSwatch[];
  fonts: BrandFontRole[];
}

const RENDER_PREFIXES = ["/brand/", "/media/"];

/** `<img src>` / CSS URL of an asset's bytes (same origin as the app). */
export function assetContentUrl(id: string): string {
  return `/api/assets/${encodeURIComponent(id)}/content`;
}

/** `/media/<id>.<ext>` → the asset; `/brand/<path>` → the brand file's asset; else null. */
export function resolveVirtualUrl(url: string, files: Record<string, string>): string | null {
  if (url.startsWith("/media/")) {
    const name = decodeURIComponent(url.slice("/media/".length).split(/[?#]/)[0] ?? "");
    const id = name.replace(/\.[A-Za-z0-9]+$/, "");
    return id ? assetContentUrl(id) : null;
  }
  if (url.startsWith("/brand/")) {
    const path = decodeURIComponent(url.slice("/brand/".length).split(/[?#]/)[0] ?? "");
    const id = files[path];
    return id ? assetContentUrl(id) : null;
  }
  return null;
}

function fileAssets(tokens: Record<string, unknown>): Record<string, string> {
  const raw = tokens.fileAssets;
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return {};
  const out: Record<string, string> = {};
  for (const [file, id] of Object.entries(raw as Record<string, unknown>)) {
    if (
      typeof id === "string" &&
      /^[A-Za-z0-9_][A-Za-z0-9._/-]*$/.test(file) &&
      !file.includes("..")
    )
      out[file] = id;
  }
  return out;
}

function kitFrom(
  tokens: BrandTokens,
  files: Record<string, string>,
  mode: RenderKit["mode"],
): RenderKit {
  const { css } = generateBrandCss(tokens, {
    fontUrl: (f) => (files[f.path] ? assetContentUrl(files[f.path] as string) : `/brand/${f.path}`),
  });
  const swatches = Object.entries(tokens.color).map(([token, c]) => ({
    token,
    value: colorValue(c).toUpperCase(),
    use: typeof c === "object" && c && "use" in c && typeof c.use === "string" ? c.use : null,
  }));
  const fonts = Object.entries(tokens.font).map(([role, f]) => ({ role, family: f.family }));
  return {
    mode,
    tokens,
    css,
    files,
    ctx: { ...brandPatchContext(tokens), assetPrefixes: RENDER_PREFIXES },
    swatches,
    fonts,
  };
}

/** The kit the worker would render with for this profile (null / unusable: the neutral one). */
export function buildRenderKit(profile: Pick<BrandProfile, "status" | "tokens"> | null): RenderKit {
  if (profile && profile.status === "approved") {
    try {
      const raw = profile.tokens as Record<string, unknown>;
      return kitFrom(parseBrandTokens(raw), fileAssets(raw), "approved");
    } catch {
      // Unusable tokens: the worker falls back to the neutral default too.
    }
  }
  return kitFrom(parseBrandTokens(NEUTRAL_BRAND_TOKENS), {}, "neutral");
}
